def compute(vars):
    total = vars["v1"] + vars["v2"] + vars["v3"]
    count = 3
    if count == 0:
        return None
    average = total / count
    return {
        "value": average,
        "trace": {
            "values": [vars["v1"], vars["v2"], vars["v3"]],
            "total": total,
            "count": count,
            "output_meta": {
                "currency": "USD",
                "scale": "thousands",
                "unit": "monetary"
            }
        }
    }
